}

verify_step01_checksum <- function(path) {
  expected <- step01_checksums$sha256[step01_checksums$file == basename(path)]
  if (length(expected) != 1L) {
    stop("No unique Step 01 checksum found for: ", basename(path))
  }
  observed <- sha256_file(path)
  if (!identical(observed, expected)) {
    stop("Step 01 checksum mismatch for: ", path)
  }
  observed
}

pseudobulk_sha256 <- verify_step01_checksum(pseudobulk_rds)
aggregate_sha256 <- verify_step01_checksum(aggregate_rds)
significant_sha256 <- verify_step01_checksum(significant_rds)

message("Loading normalized pseudobulks and LIANA aggregate results...")

