}

if (nrow(liana_aggregate) != expected_aggregate_interactions) {
  stop("Unexpected LIANA aggregate interaction count: ", nrow(liana_aggregate))
}

interaction_keys <- c(
  "source", "target", "ligand.complex", "receptor.complex"
)

if (anyDuplicated(liana_aggregate[, interaction_keys, drop = FALSE])) {
  stop("LIANA aggregate contains duplicate interaction keys.")
}

liana_significant <- liana_aggregate %>%
