    aggregate_rank <= significance_rank_threshold
  )

if (nrow(liana_significant) != expected_significant_interactions) {
  stop("Unexpected significant LIANA interaction count: ", nrow(liana_significant))
}

saved_significant_keys <- liana_significant_saved %>%
  dplyr::select(dplyr::all_of(interaction_keys), aggregate_rank) %>%
  dplyr::arrange(dplyr::across(dplyr::all_of(interaction_keys)))
computed_significant_keys <- liana_significant %>%
  dplyr::select(dplyr::all_of(interaction_keys), aggregate_rank) %>%
  dplyr::arrange(dplyr::across(dplyr::all_of(interaction_keys)))

if (!isTRUE(all.equal(
  saved_significant_keys,
  computed_significant_keys,
  check.attributes = FALSE,
  tolerance = 0
))) {
  stop("Saved and recomputed Step 01 significant interactions are inconsistent.")
}

message("Selecting the top 3,000 aggregate-ranked single-gene LR candidates...")

candidates <- liana_aggregate %>%
  dplyr::arrange(aggregate_rank) %>%
  dplyr::slice_head(n = min(top_ranked_candidates, nrow(.))) %>%
  dplyr::filter(
    !grepl("\\|", ligand.complex),
    !grepl("\\|", receptor.complex)
  ) %>%
  dplyr::mutate(
    lig_gene = if ("ligand" %in% names(.)) ligand else ligand.complex,
    rec_gene = if ("receptor" %in% names(.)) receptor else receptor.complex
  ) %>%
  dplyr::select(
    source,
    target,
    lig_gene,
    rec_gene,
    ligand.complex,
    receptor.complex
  ) %>%
  dplyr::distinct()

if (!nrow(candidates)) {
  stop("No single-gene LR candidates remained after filtering.")
}

expression_data <- SeuratObject::LayerData(
  pseudobulk_object[[assay_use]],
  layer = "data"
)

if (!identical(colnames(expression_data), rownames(pseudobulk_metadata))) {
  stop("Normalized expression and pseudobulk metadata are not identically ordered.")
}

get_celltype_gene <- function(celltype, gene) {
  celltype <- as.character(celltype)[1]
  gene <- as.character(gene)[1]

  if (!gene %in% rownames(expression_data)) {
    return(setNames(numeric(0), character(0)))
  }

  columns <- which(as.character(pseudobulk_metadata$celltype) == celltype)
  if (!length(columns)) {
    return(setNames(numeric(0), character(0)))
  }

  values <- as.numeric(expression_data[gene, columns, drop = TRUE])
  names(values) <- as.character(pseudobulk_metadata$donor[columns])
  values
}

edge_scores_by_donor <- function(sender, receiver, ligand, receptor) {
  ligand_values <- get_celltype_gene(sender, ligand)
  receptor_values <- get_celltype_gene(receiver, receptor)
  common_donors <- intersect(names(ligand_values), names(receptor_values))

  if (!length(common_donors)) {
    return(data.frame(donor = character(0), score = numeric(0)))
  }

  data.frame(
    donor = common_donors,
    score = sqrt(
      ligand_values[common_donors] * receptor_values[common_donors]
    ),
    stringsAsFactors = FALSE
  )
}

donor_stage_map <- pseudobulk_metadata %>%
  dplyr::transmute(
    donor = as.character(donor),
    condition_stage = as.character(condition_stage)
  ) %>%
  dplyr::distinct()

if (anyDuplicated(donor_stage_map$donor)) {
  stop("At least one donor maps to more than one stage.")
}

stage_edge_activity <- function(sender, receiver, ligand, receptor) {
  per_donor <- edge_scores_by_donor(sender, receiver, ligand, receptor)
  output <- setNames(rep(0, length(stage_levels)), stage_levels)

  if (!nrow(per_donor)) {
    return(output)
  }

  summarized <- per_donor %>%
    dplyr::left_join(donor_stage_map, by = "donor") %>%
    dplyr::group_by(condition_stage) %>%
    dplyr::summarise(
      activity = median(score, na.rm = TRUE),
      .groups = "drop"
    )

  if (anyNA(summarized$condition_stage)) {
    stop("A donor-level LR score could not be assigned to a stage.")
  }

  output[as.character(summarized$condition_stage)] <- summarized$activity
  output
}

message("Calculating donor-level LR activity and stage medians...")

stage_values <- purrr::pmap(
  candidates[, c("source", "target", "lig_gene", "rec_gene")],
  function(source, target, lig_gene, rec_gene) {
    stage_edge_activity(source, target, lig_gene, rec_gene)
  }
)

stage_data <- purrr::map_dfr(
  stage_values,
  ~ tibble::as_tibble_row(as.list(.x))
)

stage_activity <- dplyr::bind_cols(candidates, stage_data)

for (stage in setdiff(stage_levels, "F0")) {
  stage_activity[[paste0("delta_", stage, "_vs_F0")]] <-
    stage_activity[[stage]] - stage_activity[["F0"]]
}

message("Testing monotonic F0-F4 activity trends with Spearman correlation...")

stage_matrix <- as.matrix(stage_activity[, stage_levels, drop = FALSE])

stage_activity$spearman_r <- apply(stage_matrix, 1, function(values) {
  if (sum(is.finite(values)) < 3L) {
    return(NA_real_)
  }
  suppressWarnings(stats::cor(
    stage_index,
    values,
    method = "spearman",
    use = "pairwise.complete.obs"
  ))
})

stage_activity$spearman_p <- apply(stage_matrix, 1, function(values) {
  if (sum(is.finite(values)) < 3L) {
    return(NA_real_)
  }
  suppressWarnings(stats::cor.test(
    stage_index,
    values,
    method = "spearman",
    exact = FALSE
  )$p.value)
})

stage_activity$spearman_q <- stats::p.adjust(
  stage_activity$spearman_p,
  method = "BH"
)

selected_interactions <- stage_activity %>%
  dplyr::filter(
    is.finite(spearman_q),
    spearman_q <= spearman_q_threshold,
    is.finite(delta_F4_vs_F0),
    abs(delta_F4_vs_F0) >= minimum_absolute_f4_f0_delta
  ) %>%
  dplyr::arrange(desc(abs(delta_F4_vs_F0))) %>%
  dplyr::slice_head(n = selected_interaction_count) %>%
  dplyr::mutate(
    rowlab = paste(source, "→", target, "|", lig_gene, "→", rec_gene)
  )

if (nrow(selected_interactions) != selected_interaction_count) {
  stop(
    "Expected ", selected_interaction_count,
    " retained interactions but obtained ", nrow(selected_interactions), "."
  )
}

required_spatial_edges <- tibble::tribble(
  ~source, ~target, ~lig_gene, ~rec_gene,
  "Cholangiocyte", "Stellate", "NPNT", "ITGA8",
  "Cholangiocyte", "InfMac", "MMP7", "CD151",
  "Stellate", "PortalEndo", "CCL2", "ACKR1"
)

matched_spatial_edges <- required_spatial_edges %>%
  dplyr::inner_join(
    selected_interactions %>%
      dplyr::select(source, target, lig_gene, rec_gene),
    by = c("source", "target", "lig_gene", "rec_gene")
  )

if (nrow(matched_spatial_edges) != nrow(required_spatial_edges)) {
  stop("One or more retained Figure 3C interactions are absent from the top 60.")
}

selected_stage_matrix <- as.matrix(
  selected_interactions[, stage_levels, drop = FALSE]
)
selected_row_z <- t(scale(t(selected_stage_matrix)))
selected_row_z[is.na(selected_row_z)] <- 0

row_z_table <- dplyr::bind_cols(
  selected_interactions %>%
    dplyr::select(
      source,
      target,
      ligand = lig_gene,
      receptor = rec_gene,
      rowlab
    ),
  as.data.frame(selected_row_z, check.names = FALSE)
)

message("Preparing chord, cholangiocyte-partner, and dot-plot input tables...")

chord_frequency <- liana_significant %>%
  dplyr::count(source, target, name = "n") %>%
  tidyr::complete(
    source = cell_types,
    target = cell_types,
    fill = list(n = 0L)
  ) %>%
  dplyr::mutate(
    source = factor(source, levels = cell_types),
    target = factor(target, levels = cell_types)
  ) %>%
  dplyr::arrange(source, target) %>%
  dplyr::mutate(
    source = as.character(source),
    target = as.character(target)
  )

chord_matrix <- chord_frequency %>%
  tidyr::pivot_wider(names_from = target, values_from = n) %>%
  tibble::column_to_rownames("source") %>%
  as.matrix()

chord_matrix <- chord_matrix[cell_types, cell_types, drop = FALSE]

if (sum(chord_matrix) != expected_significant_interactions) {
  stop("Chord counts do not sum to the significant-interaction count.")
}

cholangiocyte_interactions <- liana_significant %>%
  dplyr::filter(source == "Cholangiocyte" | target == "Cholangiocyte") %>%
  dplyr::mutate(
    direction = ifelse(
      source == "Cholangiocyte",
      "outgoing (Chol -> other)",
      "incoming (other -> Chol)"
    ),
    partner = ifelse(source == "Cholangiocyte", target, source)
  )

cholangiocyte_partner_counts <- cholangiocyte_interactions %>%
  dplyr::count(direction, partner, name = "n_lr_pairs") %>%
  dplyr::arrange(direction, desc(n_lr_pairs))

cholangiocyte_top_lr <- cholangiocyte_interactions %>%
  dplyr::group_by(
    direction,
    partner,
    ligand.complex,
    receptor.complex
  ) %>%
  dplyr::summarise(
    best_rank = min(aggregate_rank),
    .groups = "drop"
  ) %>%
  dplyr::arrange(direction, partner, best_rank) %>%
  dplyr::group_by(direction, partner) %>%
  dplyr::slice_head(n = 10L) %>%
  dplyr::ungroup()

selected_keys <- selected_interactions %>%
  dplyr::select(dplyr::all_of(interaction_keys))

make_dotplot_input <- function(stage) {
  delta_column <- paste0("delta_", stage, "_vs_F0")

  selected_keys %>%
    dplyr::inner_join(
      stage_activity %>%
        dplyr::select(
          dplyr::all_of(interaction_keys),
          dplyr::all_of(stage),
          dplyr::all_of(delta_column)
        ),
      by = interaction_keys
    ) %>%
    dplyr::mutate(
      comparison = paste0(stage, " vs F0"),
      delta_pos = pmax(.data[[delta_column]], 0)
    ) %>%
    dplyr::arrange(desc(delta_pos), desc(.data[[stage]]))
}

dotplot_inputs <- setNames(
  lapply(stage_levels[-1], make_dotplot_input),
  stage_levels[-1]
)

dotplot_row_counts <- vapply(dotplot_inputs, nrow, integer(1))
if (any(dotplot_row_counts != selected_interaction_count)) {
  stop("At least one dot-plot input does not contain exactly 60 interactions.")
}

finite_tests <- sum(is.finite(stage_activity$spearman_p))
significant_trends <- sum(
  is.finite(stage_activity$spearman_q) &
    stage_activity$spearman_q <= spearman_q_threshold
)
effect_size_pass <- sum(
  is.finite(stage_activity$spearman_q) &
    stage_activity$spearman_q <= spearman_q_threshold &
    is.finite(stage_activity$delta_F4_vs_F0) &
    abs(stage_activity$delta_F4_vs_F0) >= minimum_absolute_f4_f0_delta
)

