)

if (!identical(input_manifest$sha256[1], pseudobulk_sha256) ||
    !identical(input_manifest$sha256[2], aggregate_sha256) ||
    !identical(input_manifest$sha256[3], significant_sha256)) {
  stop("Internal Step 02 input-manifest checksum inconsistency.")
}

session_lines <- capture.output(sessionInfo())

message("Saving retained Step 02 analysis outputs...")

atomic_save_rds(stage_activity, output_paths[["stage_activity_rds"]])
atomic_write_csv(stage_activity, output_paths[["stage_activity_csv"]])
atomic_save_rds(selected_interactions, output_paths[["selected_rds"]])
atomic_write_csv(selected_interactions, output_paths[["selected_csv"]])
atomic_write_csv(row_z_table, output_paths[["row_z_csv"]])
atomic_save_rds(chord_matrix, output_paths[["chord_rds"]])
atomic_write_csv(chord_frequency, output_paths[["chord_csv"]])
atomic_write_csv(
  cholangiocyte_partner_counts,
  output_paths[["cholangiocyte_counts_csv"]]
)
atomic_write_csv(
  cholangiocyte_top_lr,
  output_paths[["cholangiocyte_top_lr_csv"]]
)
atomic_write_csv(dotplot_inputs[["F1"]], output_paths[["dotplot_f1_csv"]])
atomic_write_csv(dotplot_inputs[["F2"]], output_paths[["dotplot_f2_csv"]])
atomic_write_csv(dotplot_inputs[["F3"]], output_paths[["dotplot_f3_csv"]])
atomic_write_csv(dotplot_inputs[["F4"]], output_paths[["dotplot_f4_csv"]])
atomic_write_tsv(statistical_summary, output_paths[["statistics_tsv"]])
atomic_write_tsv(parameter_table, output_paths[["parameters_tsv"]])
atomic_write_tsv(input_manifest, output_paths[["input_manifest_tsv"]])
atomic_write_lines(session_lines, output_paths[["session_info_txt"]])

output_checksums <- data.frame(
  file = basename(unname(output_paths)),
  bytes = unname(file.info(unname(output_paths))$size),
  sha256 = vapply(unname(output_paths), sha256_file, character(1)),
  stringsAsFactors = FALSE
)

checksum_path <- file.path(output_dir, "02_OUTPUT_SHA256.tsv")
atomic_write_tsv(output_checksums, checksum_path)

finished_at <- Sys.time()

completion_table <- data.frame(
  field = c(
    "status",
    "started_at",
    "finished_at",
    "elapsed_minutes",
    "script_path",
    "script_sha256",
    "single_gene_candidates_tested",
    "finite_spearman_tests",
    "bh_significant_trends",
    "effect_size_pass",
    "selected_interactions",
    "chord_significant_interactions",
    "cholangiocyte_participating_interactions",
    "dotplot_input_tables"
  ),
  value = c(
    "complete",
    format(started_at, tz = "UTC", usetz = TRUE),
    format(finished_at, tz = "UTC", usetz = TRUE),
    sprintf("%.3f", as.numeric(difftime(finished_at, started_at, units = "mins"))),
    script_path,
    if (is.na(script_path)) NA_character_ else sha256_file(script_path),
    nrow(stage_activity),
    finite_tests,
    significant_trends,
    effect_size_pass,
    nrow(selected_interactions),
    sum(chord_matrix),
    nrow(cholangiocyte_interactions),
    length(dotplot_inputs)
  ),
  stringsAsFactors = FALSE
)

completion_path <- file.path(output_dir, "02_COMPLETION.tsv")
atomic_write_tsv(completion_table, completion_path)

message("Figure 3 stage-activity analysis completed successfully at ", format(finished_at))
message("Single-gene candidates tested: ", nrow(stage_activity))
message("BH-significant trends: ", significant_trends)
message("Effect-size-qualified interactions: ", effect_size_pass)
message("Selected interactions: ", nrow(selected_interactions))
